  sunElevation: 55,        // degrees; south (−X) always
  wakeCenterY: 0.0,        // sim-hull lead vs image (UC −0.5)
  zoom: 'in',              // 'in' = open WIDE (yacht small, whole sea) and close in as she steams; 'out' = UC's frame (open close, climb away)
  zoomEnd: 0.85,           // for zoom:'in' — how far toward the close-up by p=1. 0.85 ends with her ≈ 0.46 of the screen width = her size in the berthing footage (no letterbox at the match cut)
  // 29 Sep 2026, Simon, fifth live look ("REPLICATE THE STARTING POINT AND VIEW FROM THE GAME. STOP GUESSING"):
