  islandsOpacity: 0.55,
  coast: true,
  // 30 Sep 2026, Simon: "STOP GUESSING AND EYEBALLING THINGS." The coastScale compression (was 0.25) and the
  // explicit coastShowFrom gate (was 0.16) were both built to work around what turned out to be a real
